insert into recipes (id, household_id, title, role, min_age_months, max_age_months, protein_group, cook_method, ingredients, instructions, source) values
('seed_main_pork_soy_stirfry', null, 'หมูบดผัดซีอิ๊ว', 'main', 12, null, 'pork', 'stir_fry', '[{"ingredientId":"pork_minced","amountPerPortion":40},{"ingredientId":"onion","amountPerPortion":15},{"ingredientId":"garlic","amountPerPortion":2},{"ingredientId":"soy_sauce_gf","amountPerPortion":5},{"ingredientId":"sugar","amountPerPortion":1},{"ingredientId":"cooking_oil","amountPerPortion":3}]'::jsonb, '["สับกระเทียม หั่นหอมใหญ่เป็นชิ้นเล็ก","ตั้งกระทะ ใส่น้ำมัน ผัดกระเทียมและหอมใหญ่ให้หอม","ใส่หมูบดผัดจนสุก ปรุงด้วยซีอิ๊วขาวสูตรไม่มีกลูเตนและน้ำตาล","ผัดจนเข้ากัน พักให้เย็นก่อนแบ่งใส่กล่อง"]'::jsonb, 'seed'),
('seed_main_pork_winter_melon_soup', null, 'แกงจืดฟักหมูสับ', 'main', 12, null, 'pork', 'boil', '[{"ingredientId":"winter_melon","amountPerPortion":50},{"ingredientId":"pork_minced","amountPerPortion":30},{"ingredientId":"garlic","amountPerPortion":1},{"ingredientId":"salt","amountPerPortion":0.5}]'::jsonb, '["ต้มน้ำให้เดือด ปั้นหมูสับเป็นก้อนเล็กลงต้มจนสุก","ใส่ฟักหั่นชิ้นพอดีคำ ต้มจนนุ่ม","ปรุงเกลือเล็กน้อย ใส่กระเทียม","พักให้เย็น แยกเนื้อกับน้ำแกงใส่กล่อง"]'::jsonb, 'seed'),
('seed_main_pork_pumpkin_steamed', null, 'หมูสับนึ่งฟักทอง', 'main', 12, null, 'pork', 'steam', '[{"ingredientId":"pumpkin","amountPerPortion":40},{"ingredientId":"pork_minced","amountPerPortion":30},{"ingredientId":"garlic","amountPerPortion":1},{"ingredientId":"soy_sauce_gf","amountPerPortion":3}]'::jsonb, '["หั่นฟักทองเป็นชิ้นบาง เรียงในจาน","คลุกหมูสับกับกระเทียมสับและซีอิ๊วขาวสูตรไม่มีกลูเตน วางบนฟักทอง","นึ่งไฟแรงประมาณ 15 นาทีจนสุก","พักให้เย็นก่อนแบ่งใส่กล่อง"]'::jsonb, 'seed'),
('seed_main_pork_veg_balls_baked', null, 'ลูกชิ้นหมูผักอบ', 'main', 12, null, 'pork', 'bake', '[{"ingredientId":"pork_minced","amountPerPortion":40},{"ingredientId":"carrot","amountPerPortion":15},{"ingredientId":"tapioca_flour","amountPerPortion":5},{"ingredientId":"garlic","amountPerPortion":1},{"ingredientId":"soy_sauce_gf","amountPerPortion":2},{"ingredientId":"cooking_oil","amountPerPortion":2}]'::jsonb, '["ขูดแครอทฝอย สับกระเทียม","นวดหมูสับ แครอท กระเทียม ซีอิ๊วขาวสูตรไม่มีกลูเตน และแป้งมันสำปะหลังให้เหนียว (ใช้แป้งมันแทนแป้งสาลี)","ปั้นเป็นก้อนเล็ก ทาน้ำมันบางๆ","อบ 180°C ประมาณ 20 นาทีจนสุก พักให้เย็นก่อนแช่แข็ง"]'::jsonb, 'seed'),
('seed_main_pork_kale_stirfry', null, 'ผัดคะน้าหมูสับ', 'main', 12, null, 'pork', 'stir_fry', '[{"ingredientId":"chinese_kale","amountPerPortion":40},{"ingredientId":"pork_minced","amountPerPortion":30},{"ingredientId":"garlic","amountPerPortion":2},{"ingredientId":"soy_sauce_gf","amountPerPortion":4},{"ingredientId":"cooking_oil","amountPerPortion":3}]'::jsonb, '["หั่นคะน้าเป็นชิ้นสั้นพอดีคำ สับกระเทียม","ผัดกระเทียมกับหมูสับจนสุก","ใส่คะน้า ปรุงด้วยซีอิ๊วขาวสูตรไม่มีกลูเตน ผัดจนนุ่ม","พักให้เย็นก่อนแบ่งใส่กล่อง"]'::jsonb, 'seed'),
('seed_puree_pork', null, 'หมูบดละเอียด', 'puree', 6, null, 'pork', 'boil', '[{"ingredientId":"pork_minced","amountPerPortion":20}]'::jsonb, '["ต้มหมูบดกับน้ำจนสุกนุ่ม","ปั่นกับน้ำต้มจนละเอียด","เทใส่ถาดน้ำแข็ง แช่แข็งเป็นก้อน"]'::jsonb, 'seed'),
('seed_puree_rice', null, 'ข้าวบด', 'puree', 6, null, null, 'boil', '[{"ingredientId":"jasmine_rice","amountPerPortion":30}]'::jsonb, '["ต้มข้าวกับน้ำมากๆ จนเละ","ปั่นให้ละเอียด","เทใส่ถาดน้ำแข็ง แช่แข็งเป็นก้อน"]'::jsonb, 'seed'),
('seed_puree_sweet_potato', null, 'มันเทศบด', 'puree', 6, null, null, 'steam', '[{"ingredientId":"sweet_potato","amountPerPortion":30}]'::jsonb, '["ปอกเปลือก หั่นชิ้น นึ่งจนนุ่ม","บดหรือปั่นให้ละเอียด","เทใส่ถาดน้ำแข็ง แช่แข็งเป็นก้อน"]'::jsonb, 'seed'),
('seed_puree_riceberry', null, 'ข้าวไรซ์เบอร์รี่บด', 'puree', 6, null, null, 'boil', '[{"ingredientId":"riceberry","amountPerPortion":30}]'::jsonb, '["ต้มข้าวไรซ์เบอร์รี่กับน้ำมากๆ จนเละ","ปั่นให้ละเอียด","เทใส่ถาดน้ำแข็ง แช่แข็งเป็นก้อน"]'::jsonb, 'seed'),
