('seed_puree_winter_melon', null, 'ฟักบด', 'puree', 6, null, null, 'steam', '[{"ingredientId":"winter_melon","amountPerPortion":30}]'::jsonb, '["ปอกเปลือก หั่นชิ้น นึ่งจนนุ่ม","ปั่นให้ละเอียด","เทใส่ถาดน้ำแข็ง แช่แข็งเป็นก้อน"]'::jsonb, 'seed'),
